mapper.select:
SELECT COUNT(*)
FROM outbox_event
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND operation_id=#{operationId}

mapper.update:
UPDATE outbox_event
SET status='CLAIMED', claim_epoch=claim_epoch+1, lease_until=#{leaseUntil}, version=version+1, updated_at=#{now}
WHERE event_id=#{eventId}
AND claim_epoch=#{claimEpoch}
AND (status='PENDING' OR (status='CLAIMED'
AND lease_until<#{now}))

UPDATE outbox_event
SET status='PUBLISHED', published_at=#{now}, lease_until=NULL, next_attempt_at=#{now}, version=version+1, updated_at=#{now}
WHERE event_id=#{eventId}
AND claim_epoch=#{claimEpoch}
AND status='CLAIMED'

UPDATE outbox_event
SET status='PENDING', lease_until=NULL, next_attempt_at=#{nextAttemptAt}, version=version+1, updated_at=#{now}
WHERE event_id=#{eventId}
AND claim_epoch=#{claimEpoch}
AND status='CLAIMED'

UPDATE outbox_event
SET status='ISOLATED', lease_until=NULL, version=version+1, updated_at=#{now}
WHERE event_id=#{eventId}
AND claim_epoch=#{claimEpoch}
AND status='CLAIMED'
